'use strict';
// Load all synthetic filtering test documents.
// Run in Query Console against the TEST CONTENT database.
// Documents are defined inline so no filesystem access is needed.
declareUpdate();

const COLLECTION = 'filtering-validation';
const PERMISSIONS = [
  xdmp.permission('rest-reader', 'read'),
  xdmp.permission('rest-writer', 'update'),
];

// Minimal item document factory. All docs are HumanMadeObject with itemAnyText-eligible content.
function makeDoc(id, names, descriptions) {
  const identified_by = names.map((n) => ({
    type: 'Name',
    content: n,
    classified_as: [
      {
        id: 'https://lux.collections.yale.edu/data/concept/f7ef5bb4-e7fb-443d-9c6b-371a23e717ec',
        type: 'Type',
        _label: 'Primary Name',
        equivalent: [
          { id: 'http://vocab.getty.edu/aat/300404670', type: 'Type' },
        ],
      },
    ],
  }));
  const referred_to_by = (descriptions || []).map((d) => ({
    type: 'LinguisticObject',
    content: d,
    classified_as: [
      {
        id: 'https://lux.collections.yale.edu/data/concept/b9d84f17-662e-46ef-ab8b-7499717f8337',
        type: 'Type',
        _label: 'Description',
        equivalent: [
          { id: 'http://vocab.getty.edu/aat/300435416', type: 'Type' },
        ],
      },
    ],
  }));
  return {
    json: {
      id: `https://lux.collections.yale.edu/data/test/${id}`,
      type: 'HumanMadeObject',
      _label: `Test ${id}`,
      identified_by,
      referred_to_by,
      classified_as: [
        {
          id: 'https://lux.collections.yale.edu/data/concept/test-type-1',
          type: 'Type',
        },
      ],
    },
    triples: [],
    admin: {},
    indexedProperties: { dataType: 'HumanMadeObject' },
  };
}

const docs = [
  {
    uri: '/test/filtering/item-001.json',
    content: makeDoc(
      'item-001',
      ['Georgia Landscape'],
      ['Painted by Keeffe in 1920'],
    ),
  },
  {
    uri: '/test/filtering/item-002.json',
    content: makeDoc('item-002', ['Portrait of Georgia Keeffe'], []),
  },
  {
    uri: '/test/filtering/item-003.json',
    content: makeDoc('item-003', ["O'Keeffe Exhibition Catalog"], []),
  },
  {
    uri: '/test/filtering/item-004.json',
    content: makeDoc('item-004', ['O Keeffe Collection Guide'], []),
  },
  {
    uri: '/test/filtering/item-005.json',
    content: makeDoc('item-005', ['OKeeffe Digital Archive'], []),
  },
  {
    uri: '/test/filtering/item-006.json',
    content: makeDoc(
      'item-006',
      ['Stieglitz Photograph'],
      ['Held in the Beinecke Rare Book and Manuscript Library'],
    ),
  },
  {
    uri: '/test/filtering/item-007.json',
    content: makeDoc(
      'item-007',
      ['Stieglitz Cloud Study'],
      ['A gelatin silver print from the museum collection'],
    ),
  },
  {
    uri: '/test/filtering/item-008.json',
    content: makeDoc('item-008', ['PAINTING BY UNKNOWN ARTIST'], []),
  },
  {
    uri: '/test/filtering/item-009.json',
    content: makeDoc('item-009', ['A painting of the seaside'], []),
  },
  {
    uri: '/test/filtering/item-010.json',
    content: makeDoc('item-010', ['Painting of Flowers'], []),
  },
  {
    uri: '/test/filtering/item-011.json',
    content: makeDoc('item-011', ['Collection of watercolor paintings'], []),
  },
  {
    uri: '/test/filtering/item-012.json',
    content: makeDoc('item-012', ['Self-portrait in Blue'], []),
  },
  {
    uri: '/test/filtering/item-013.json',
    content: makeDoc('item-013', ['Self portrait in Red'], []),
  },
  {
    uri: '/test/filtering/item-014.json',
    content: makeDoc('item-014', ['Selfportrait with Hat'], []),
  },
];

let loaded = 0;
let skipped = 0;

for (const doc of docs) {
  if (fn.docAvailable(doc.uri)) {
    skipped++;
    continue;
  }
  xdmp.documentInsert(doc.uri, doc.content, {
    collections: [COLLECTION],
    permissions: PERMISSIONS,
  });
  loaded++;
}

const results = {
  loaded,
  skipped,
  total: docs.length,
  collection: COLLECTION,
  message: `Loaded ${loaded} documents, skipped ${skipped} (already exist). Collection: ${COLLECTION}`,
};
export default results;

'use strict';
// V1: Cross-instance phrase matching
// Tests whether a phrase query for "Georgia Keeffe" matches a document where
// "Georgia" and "Keeffe" appear in SEPARATE content nodes (different field instances).
//
// Expected: item-002 matches (phrase exists in single content node).
//           item-001 should NOT match (words are in different content nodes).
//           If item-001 matches unfiltered, that is a false positive.

const op = require('/MarkLogic/optic');

const COLLECTION = 'filtering-validation';
const SCOPE_CONSTRAINT = cts.collectionQuery(COLLECTION);

// The phrase query: "Georgia Keeffe" as a phrase (complete match = fieldValueQuery)
// and as adjacent words (fieldWordQuery with the phrase as a single string).
const phraseWordQuery = cts.fieldWordQuery(
  'itemAnyText',
  'Georgia Keeffe',
  [
    'case-insensitive',
    'diacritic-insensitive',
    'punctuation-insensitive',
    'whitespace-insensitive',
    'stemmed',
    'wildcarded',
  ],
  1,
);

const scopedPhraseQuery = cts.andQuery([SCOPE_CONSTRAINT, phraseWordQuery]);

// 1. Unfiltered (cts.uris)
const unfilteredUris = cts
  .uris(null, [], scopedPhraseQuery)
  .toArray()
  .map(String);

// 2. Filtered (cts.search)
const filteredUris = [];
for (const doc of cts.search(scopedPhraseQuery)) {
  filteredUris.push(String(fn.documentUri(doc)));
}

// 3. Optic plan (non-semantic keyword path)
const opticPlan = op
  .fromLexicons(
    {
      uri: cts.uriReference(),
      iri: cts.iriReference(),
      dataType: cts.fieldReference('anyDataTypeName', [
        'type=string',
        'collation=http://marklogic.com/collation/codepoint',
      ]),
    },
    null,
    op.fragmentIdCol('frag'),
  )
  .where(cts.collectionQuery(COLLECTION))
  .where(op.in(op.col('dataType'), ['DigitalObject', 'HumanMadeObject']))
  .joinInner(
    op.fromSearch(phraseWordQuery, null, null, { scoreMethod: 'logtfidf' }),
    op.on(op.fragmentIdCol('frag'), op.fragmentIdCol('fragmentId')),
  )
  .groupBy(['uri'], [op.sample('dataType', op.col('dataType'))])
  .select([op.as('id', op.col('uri')), op.as('type', op.col('dataType'))]);

const opticUris = opticPlan
  .result()
  .toArray()
  .map((r) => r.id);

const results = {
  scenario: 'V1: Cross-instance phrase matching',
  query: 'fieldWordQuery("itemAnyText", "Georgia Keeffe", [default options])',
  description:
    'Tests whether words in separate //content nodes produce a false-positive phrase match.',
  expectedMatch: ['/test/filtering/item-002.json'],
  expectedNoMatch: ['/test/filtering/item-001.json'],
  unfiltered: { count: unfilteredUris.length, uris: unfilteredUris.sort() },
  filtered: { count: filteredUris.length, uris: filteredUris.sort() },
  optic: { count: opticUris.length, uris: opticUris.sort() },
  falsePositives: unfilteredUris.filter((u) => !filteredUris.includes(u)),
  opticVsFiltered: opticUris.filter((u) => !filteredUris.includes(u)),
  analysis: {
    unfilteredMatchesFiltered: unfilteredUris.length === filteredUris.length,
    opticMatchesFiltered: opticUris.length === filteredUris.length,
    hasFalsePositives: unfilteredUris.length > filteredUris.length,
  },
};
export default results;

'use strict';
// Delete all synthetic filtering test documents.
// Run in Query Console against the TEST CONTENT database.
declareUpdate();

const COLLECTION = 'filtering-validation';

const uris = cts.uris(null, [], cts.collectionQuery(COLLECTION)).toArray();

for (const uri of uris) {
  xdmp.documentDelete(uri);
}

const results = {
  deleted: uris.length,
  collection: COLLECTION,
  message: `Deleted ${uris.length} documents from collection '${COLLECTION}'.`,
};
export default results;

'use strict';
// V2: Case sensitivity
// Tests whether case-sensitive search correctly distinguishes case variants.
// Bob Starbird: "unfiltered case-sensitive searches of lower-case queries
// cannot eliminate false positives" — even WITH fast-case-sensitive-searches.
//
// Test A: case-sensitive search for "PAINTING" (upper) — should match item-008 only.
// Test B: case-sensitive search for "painting" (lower) — Bob says this MAY
//         produce false positives (matches upper-case too) unfiltered.
// Test C: case-insensitive search for "painting" — should match all three (008, 009, 010).

const op = require('/MarkLogic/optic');

const COLLECTION = 'filtering-validation';
const SCOPE_CONSTRAINT = cts.collectionQuery(COLLECTION);
const SCOPE_TYPES = ['DigitalObject', 'HumanMadeObject'];

function buildOpticPlan(ctsQuery) {
  return op
    .fromLexicons(
      {
        uri: cts.uriReference(),
        iri: cts.iriReference(),
        dataType: cts.fieldReference('anyDataTypeName', [
          'type=string',
          'collation=http://marklogic.com/collation/codepoint',
        ]),
      },
      null,
      op.fragmentIdCol('frag'),
    )
    .where(cts.collectionQuery(COLLECTION))
    .where(op.in(op.col('dataType'), SCOPE_TYPES))
    .joinInner(
      op.fromSearch(ctsQuery, null, null, { scoreMethod: 'logtfidf' }),
      op.on(op.fragmentIdCol('frag'), op.fragmentIdCol('fragmentId')),
    )
    .groupBy(['uri'], [op.sample('dataType', op.col('dataType'))])
    .select([op.as('id', op.col('uri')), op.as('type', op.col('dataType'))]);
}

function runScenario(label, ctsQuery) {
  const scopedQuery = cts.andQuery([SCOPE_CONSTRAINT, ctsQuery]);
  const unfilteredUris = cts.uris(null, [], scopedQuery).toArray().map(String);
  const filteredUris = [];
  for (const doc of cts.search(scopedQuery)) {
    filteredUris.push(String(fn.documentUri(doc)));
  }
  const opticUris = buildOpticPlan(ctsQuery)
    .result()
    .toArray()
    .map((r) => r.id);

  return {
    label,
    unfiltered: { count: unfilteredUris.length, uris: unfilteredUris.sort() },
    filtered: { count: filteredUris.length, uris: filteredUris.sort() },
    optic: { count: opticUris.length, uris: opticUris.sort() },
    falsePositives: unfilteredUris.filter((u) => !filteredUris.includes(u)),
    opticVsFiltered: opticUris.filter((u) => !filteredUris.includes(u)),
    unfilteredMatchesFiltered: unfilteredUris.length === filteredUris.length,
    opticMatchesFiltered: opticUris.length === filteredUris.length,
  };
}

// Test A: case-sensitive "PAINTING"
const testA = runScenario(
  'A: case-sensitive "PAINTING" (upper)',
  cts.fieldWordQuery(
    'itemAnyText',
    'PAINTING',
    [
      'case-sensitive',
      'diacritic-insensitive',
      'punctuation-insensitive',
      'whitespace-insensitive',
      'stemmed',
      'wildcarded',
    ],
    1,
  ),
);

// Test B: case-sensitive "painting" (lower) — Bob's known false-positive trigger
const testB = runScenario(
  'B: case-sensitive "painting" (lower)',
  cts.fieldWordQuery(
    'itemAnyText',
    'painting',
    [
      'case-sensitive',
      'diacritic-insensitive',
      'punctuation-insensitive',
      'whitespace-insensitive',
      'stemmed',
      'wildcarded',
    ],
    1,
  ),
);

// Test C: case-insensitive "painting" (baseline)
const testC = runScenario(
  'C: case-insensitive "painting" (baseline)',
  cts.fieldWordQuery(
    'itemAnyText',
    'painting',
    [
      'case-insensitive',
      'diacritic-insensitive',
      'punctuation-insensitive',
      'whitespace-insensitive',
      'stemmed',
      'wildcarded',
    ],
    1,
  ),
);

const results = {
  scenario: 'V2: Case sensitivity',
  description:
    'Tests case-sensitive search accuracy. Bob Starbird notes lower-case case-sensitive queries cannot eliminate false positives even with fast-case-sensitive-searches.',
  expectedBehavior: {
    testA: 'Only item-008 (PAINTING) should match',
    testB:
      'Only item-009 (painting) should match — but Bob says false positives from item-008/010 are possible',
    testC:
      'All three (008, 009, 010) plus item-011 (paintings via stemming) should match',
  },
  testA,
  testB,
  testC,
};
export default results;

'use strict';
// V3: Punctuation sensitivity
// Tests whether punctuation-sensitive search distinguishes O'Keeffe variants.
// Bob Starbird: "Punctuation and space tokens are not indexed as words in the
// universal index. Use of punctuation in the query will allow false positives."
//
// Test A: punctuation-insensitive "o'keeffe" — should match item-003, item-004, possibly item-005.
// Test B: punctuation-sensitive "o'keeffe" — should match ONLY item-003.
// Test C: punctuation-sensitive "self-portrait" — should match ONLY item-012.
// Test D: punctuation-insensitive "self-portrait" — should match item-012, item-013, possibly item-014.

const op = require('/MarkLogic/optic');

const COLLECTION = 'filtering-validation';
const SCOPE_CONSTRAINT = cts.collectionQuery(COLLECTION);
const SCOPE_TYPES = ['DigitalObject', 'HumanMadeObject'];

function buildOpticPlan(ctsQuery) {
  return op
    .fromLexicons(
      {
        uri: cts.uriReference(),
        iri: cts.iriReference(),
        dataType: cts.fieldReference('anyDataTypeName', [
          'type=string',
          'collation=http://marklogic.com/collation/codepoint',
        ]),
      },
      null,
      op.fragmentIdCol('frag'),
    )
    .where(cts.collectionQuery(COLLECTION))
    .where(op.in(op.col('dataType'), SCOPE_TYPES))
    .joinInner(
      op.fromSearch(ctsQuery, null, null, { scoreMethod: 'logtfidf' }),
      op.on(op.fragmentIdCol('frag'), op.fragmentIdCol('fragmentId')),
    )
    .groupBy(['uri'], [op.sample('dataType', op.col('dataType'))])
    .select([op.as('id', op.col('uri')), op.as('type', op.col('dataType'))]);
}

function runScenario(label, ctsQuery) {
  const scopedQuery = cts.andQuery([SCOPE_CONSTRAINT, ctsQuery]);
  const unfilteredUris = cts.uris(null, [], scopedQuery).toArray().map(String);
  const filteredUris = [];
  for (const doc of cts.search(scopedQuery)) {
    filteredUris.push(String(fn.documentUri(doc)));
  }
  const opticUris = buildOpticPlan(ctsQuery)
    .result()
    .toArray()
    .map((r) => r.id);

  return {
    label,
    unfiltered: { count: unfilteredUris.length, uris: unfilteredUris.sort() },
    filtered: { count: filteredUris.length, uris: filteredUris.sort() },
    optic: { count: opticUris.length, uris: opticUris.sort() },
    falsePositives: unfilteredUris.filter((u) => !filteredUris.includes(u)),
    opticVsFiltered: opticUris.filter((u) => !filteredUris.includes(u)),
    unfilteredMatchesFiltered: unfilteredUris.length === filteredUris.length,
    opticMatchesFiltered: opticUris.length === filteredUris.length,
  };
}

// Test A: punctuation-insensitive "o'keeffe"
const testA = runScenario(
  'A: punctuation-insensitive "o\'keeffe"',
  cts.fieldWordQuery(
    'itemAnyText',
    "o'keeffe",
    [
      'case-insensitive',
      'diacritic-insensitive',
      'punctuation-insensitive',
      'whitespace-insensitive',
      'stemmed',
      'wildcarded',
    ],
    1,
  ),
);

// Test B: punctuation-sensitive "o'keeffe"
const testB = runScenario(
  'B: punctuation-sensitive "o\'keeffe"',
  cts.fieldWordQuery(
    'itemAnyText',
    "o'keeffe",
    [
      'case-insensitive',
      'diacritic-insensitive',
      'punctuation-sensitive',
      'whitespace-insensitive',
      'stemmed',
      'wildcarded',
    ],
    1,
  ),
);

// Test C: punctuation-sensitive "self-portrait"
const testC = runScenario(
  'C: punctuation-sensitive "self-portrait"',
  cts.fieldWordQuery(
    'itemAnyText',
    'self-portrait',
    [
      'case-insensitive',
      'diacritic-insensitive',
      'punctuation-sensitive',
      'whitespace-insensitive',
      'stemmed',
      'wildcarded',
    ],
    1,
  ),
);

// Test D: punctuation-insensitive "self-portrait"
const testD = runScenario(
  'D: punctuation-insensitive "self-portrait"',
  cts.fieldWordQuery(
    'itemAnyText',
    'self-portrait',
    [
      'case-insensitive',
      'diacritic-insensitive',
      'punctuation-insensitive',
      'whitespace-insensitive',
      'stemmed',
      'wildcarded',
    ],
    1,
  ),
);

const results = {
  scenario: 'V3: Punctuation sensitivity',
  description:
    'Tests punctuation-sensitive search accuracy. Bob: punctuation tokens are not indexed; punctuation in queries allows false positives.',
  expectedBehavior: {
    testA:
      "Broad match: item-003 (O'Keeffe), item-004 (O Keeffe), possibly item-005 (OKeeffe)",
    testB:
      "Strict: only item-003 (O'Keeffe) should match after filtering. Unfiltered may include false positives.",
    testC:
      'Strict: only item-012 (Self-portrait) after filtering. Unfiltered may include item-013 (self portrait).',
    testD:
      'Broad: item-012 (Self-portrait) and item-013 (self portrait), possibly item-014 (Selfportrait)',
  },
  testA,
  testB,
  testC,
  testD,
};
export default results;

'use strict';
// V4: NOT with approximate sub-query
// Mirrors the UAT finding: (stieglitz OR o'keeffe) AND NOT library
// If "library" word query has false positives (unlikely for a simple word),
// NOT would produce false negatives. More importantly, this tests whether
// Optic's notExistsJoin / CTS fold correctly excludes documents.
//
// Expected: item-007 matches (has stieglitz, no library).
//           item-006 should NOT match (has stieglitz AND library).
//           item-003 matches (has o'keeffe, no library).

const op = require('/MarkLogic/optic');

const COLLECTION = 'filtering-validation';
const SCOPE_CONSTRAINT = cts.collectionQuery(COLLECTION);
const SCOPE_TYPES = ['DigitalObject', 'HumanMadeObject'];

const DEFAULT_OPTIONS = [
  'case-insensitive',
  'diacritic-insensitive',
  'punctuation-insensitive',
  'whitespace-insensitive',
  'stemmed',
  'wildcarded',
];

// The full query: (stieglitz OR o'keeffe) AND NOT library
const stieglitzQuery = cts.fieldWordQuery(
  'itemAnyText',
  'stieglitz',
  DEFAULT_OPTIONS,
  1,
);
const okeeffeQuery = cts.fieldWordQuery(
  'itemAnyText',
  "o'keeffe",
  DEFAULT_OPTIONS,
  1,
);
const libraryQuery = cts.fieldWordQuery(
  'itemAnyText',
  'library',
  DEFAULT_OPTIONS,
  1,
);

const combinedQuery = cts.andNotQuery(
  cts.orQuery([stieglitzQuery, okeeffeQuery]),
  libraryQuery,
);

const scopedQuery = cts.andQuery([SCOPE_CONSTRAINT, combinedQuery]);

// 1. Unfiltered
const unfilteredUris = cts.uris(null, [], scopedQuery).toArray().map(String);

// 2. Filtered
const filteredUris = [];
for (const doc of cts.search(scopedQuery)) {
  filteredUris.push(String(fn.documentUri(doc)));
}

// 3. Optic — using the CTS query in a where clause (non-scoring path, like Opt 1)
const opticPlanWhere = op
  .fromLexicons(
    {
      uri: cts.uriReference(),
      iri: cts.iriReference(),
      dataType: cts.fieldReference('anyDataTypeName', [
        'type=string',
        'collation=http://marklogic.com/collation/codepoint',
      ]),
    },
    null,
    op.fragmentIdCol('frag'),
  )
  .where(cts.collectionQuery(COLLECTION))
  .where(op.in(op.col('dataType'), SCOPE_TYPES))
  .where(combinedQuery)
  .groupBy(['uri'], [op.sample('dataType', op.col('dataType'))])
  .select([op.as('id', op.col('uri')), op.as('type', op.col('dataType'))]);

const opticWhereUris = opticPlanWhere
  .result()
  .toArray()
  .map((r) => r.id);

// 4. Optic — using fromSearch (scoring path)
const opticPlanFromSearch = op
  .fromLexicons(
    {
      uri: cts.uriReference(),
      iri: cts.iriReference(),
      dataType: cts.fieldReference('anyDataTypeName', [
        'type=string',
        'collation=http://marklogic.com/collation/codepoint',
      ]),
    },
    null,
    op.fragmentIdCol('frag'),
  )
  .where(cts.collectionQuery(COLLECTION))
  .where(op.in(op.col('dataType'), SCOPE_TYPES))
  .joinInner(
    op.fromSearch(combinedQuery, null, null, { scoreMethod: 'logtfidf' }),
    op.on(op.fragmentIdCol('frag'), op.fragmentIdCol('fragmentId')),
  )
  .groupBy(
    ['uri'],
    [
      op.sample('dataType', op.col('dataType')),
      op.max('score', op.col('score')),
    ],
  )
  .select([op.as('id', op.col('uri')), op.as('type', op.col('dataType'))]);

const opticFromSearchUris = opticPlanFromSearch
  .result()
  .toArray()
  .map((r) => r.id);

const results = {
  scenario: 'V4: NOT with approximate sub-query',
  description:
    "Tests (stieglitz OR o'keeffe) AND NOT library. Mirrors UAT finding where Optic returned 158 vs CTS 3.",
  expectedBehavior: {
    shouldMatch: [
      "item-003 (o'keeffe)",
      'item-004 (O Keeffe)',
      'item-005 (OKeeffe)',
      'item-007 (stieglitz, no library)',
    ],
    shouldNotMatch: ['item-006 (stieglitz WITH library)'],
  },
  unfiltered: { count: unfilteredUris.length, uris: unfilteredUris.sort() },
  filtered: { count: filteredUris.length, uris: filteredUris.sort() },
  opticWhere: { count: opticWhereUris.length, uris: opticWhereUris.sort() },
  opticFromSearch: {
    count: opticFromSearchUris.length,
    uris: opticFromSearchUris.sort(),
  },
  falsePositives: unfilteredUris.filter((u) => !filteredUris.includes(u)),
  falseNegatives: filteredUris.filter((u) => !unfilteredUris.includes(u)),
  opticWhereVsFiltered: opticWhereUris.filter((u) => !filteredUris.includes(u)),
  opticFromSearchVsFiltered: opticFromSearchUris.filter(
    (u) => !filteredUris.includes(u),
  ),
  analysis: {
    unfilteredMatchesFiltered: unfilteredUris.length === filteredUris.length,
    opticWhereMatchesFiltered: opticWhereUris.length === filteredUris.length,
    opticFromSearchMatchesFiltered:
      opticFromSearchUris.length === filteredUris.length,
    note: 'If unfiltered > filtered, NOT is producing false negatives (documents incorrectly excluded). If unfiltered < filtered for the positive part, the OR has false positives that NOT amplified.',
  },
};
export default results;

'use strict';
// V5: Stemming correctness
// Tests that stemmed search matches morphological variants and that
// unstemmed search correctly excludes them.
//
// Test A: stemmed "painting" — should match item-009 (painting), item-010 (Painting),
//         item-011 (paintings). May also match item-008 (PAINTING).
// Test B: unstemmed "painting" — should match exact word only (009, 010, 008),
//         NOT item-011 (paintings).

const op = require('/MarkLogic/optic');

const COLLECTION = 'filtering-validation';
const SCOPE_CONSTRAINT = cts.collectionQuery(COLLECTION);
const SCOPE_TYPES = ['DigitalObject', 'HumanMadeObject'];

function buildOpticPlan(ctsQuery) {
  return op
    .fromLexicons(
      {
        uri: cts.uriReference(),
        iri: cts.iriReference(),
        dataType: cts.fieldReference('anyDataTypeName', [
          'type=string',
          'collation=http://marklogic.com/collation/codepoint',
        ]),
      },
      null,
      op.fragmentIdCol('frag'),
    )
    .where(cts.collectionQuery(COLLECTION))
    .where(op.in(op.col('dataType'), SCOPE_TYPES))
    .joinInner(
      op.fromSearch(ctsQuery, null, null, { scoreMethod: 'logtfidf' }),
      op.on(op.fragmentIdCol('frag'), op.fragmentIdCol('fragmentId')),
    )
    .groupBy(['uri'], [op.sample('dataType', op.col('dataType'))])
    .select([op.as('id', op.col('uri')), op.as('type', op.col('dataType'))]);
}

function runScenario(label, ctsQuery) {
  const scopedQuery = cts.andQuery([SCOPE_CONSTRAINT, ctsQuery]);
  const unfilteredUris = cts.uris(null, [], scopedQuery).toArray().map(String);
  const filteredUris = [];
