// Test A: case-sensitive "stieglitz" (all lowercase query)
const testA = runScenario(
  'A: case-sensitive "stieglitz" (lower-case query)',
  cts.fieldWordQuery(
    'itemAnyText',
    'stieglitz',
    [
      'case-sensitive',
      'diacritic-insensitive',
      'punctuation-insensitive',
      'whitespace-insensitive',
      'unstemmed',
      'wildcarded',
